private int parseEndOfLine(String headerPart, int end) {
    // Find the next CRLF sequence starting from the given index.
    // The index returned points to the position of the '\r' character.
    if (headerPart == null || headerPart.isEmpty()) {
        throw new IllegalArgumentException("Header part cannot be null or empty");
    }
    if (end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("End index out of bounds: " + end);
    }
    int lineEnd = headerPart.indexOf("\r\n", end);
    if (lineEnd == -1) {
        throw new IllegalArgumentException("End of line (CRLF) not found in header part");
    }
    return lineEnd;
}

