@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Create two partitions of vertices
    java.util.List<V> left = new java.util.ArrayList<>();
    java.util.List<V> right = new java.util.ArrayList<>();

    // For demonstration, create 3 vertices in each partition
    for (int i = 1; i <= 3; i++) {
        @SuppressWarnings("unchecked")
        V vertex = (V) ("U" + i);
        target.addVertex(vertex);
        left.add(vertex);
        resultMap.put("U" + i, vertex);
    }

    for (int i = 1; i <= 3; i++) {
        @SuppressWarnings("unchecked")
        V vertex = (V) ("V" + i);
        target.addVertex(vertex);
        right.add(vertex);
        resultMap.put("V" + i, vertex);
    }

    // Connect every vertex in left to every vertex in right
    for (V u : left) {
        for (V v : right) {
            target.addEdge(u, v);
        }
    }
}

protected int findByte(byte value, int pos) {
    if (buffer == null) {
        return -1;
    }
    int start = pos;
    if (start < 0) {
        start = 0;
    }
    if (start >= buffer.length) {
        return -1;
    }
    for (int i = start; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }
    return -1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Compute the serialized size of the message using the provided schema and buffer
    int size = schema.getSerializedSize(message, buffer);

    // Create a CodedOutputStream backed by the provided OutputStream
    CodedOutputStream cos = CodedOutputStream.newInstance(out);

    // Write the length prefix as a varint
    cos.writeRawVarint32(size);

    // Serialize the message into the CodedOutputStream using the schema
    schema.writeTo(message, cos, buffer);

    // Flush the stream to ensure all bytes are written
    cos.flush();

    // Return the size of the serialized message
    return size;
}

