private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && suffix == null) {
        return true;
    }
    // If one is null but not both, no match
    if (str == null || suffix == null) {
        return false;
    }
    // Empty suffix is always a match
    if (suffix.length() == 0) {
        return true;
    }
    // If suffix is longer than the string, it cannot match
    if (suffix.length() > str.length()) {
        return false;
    }
    // Use regionMatches to compare the end of the string with the suffix
    int start = str.length() - suffix.length();
    return str.regionMatches(ignoreCase, start, suffix, 0, suffix.length());
}

