    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // If the path is absolute, ignore the leading '/'
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // Split on '/' and keep empty segments
    String[] parts = rawPath.split("/", -1);
    for (String part : parts) {
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        // Construct a PathSegmentImpl.  The constructor signature may vary;
        // here we assume a constructor that takes the segment string and a
        // flag indicating whether it is decoded.
        segments.add(new PathSegmentImpl(seg, decode));
    }
    return segments;
}

