@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or primitive char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }

    // Null values are allowed and simply return null
    if (value == null) {
        return null;
    }

    // Direct Character instance
    if (value instanceof Character) {
        return value;
    }

    // String conversion: must be exactly one character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        }
        throw new IllegalArgumentException(
            "Cannot convert String of length " + str.length() + " to Character");
    }

    // Number conversion: cast to int and then to char, ensuring range
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new IllegalArgumentException(
                "Number value out of char range: " + intVal);
        }
        return (char) intVal;
    }

    // Fallback: try toString and take first character if length is 1
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }

    // If none of the above, conversion is not possible
    throw new IllegalArgumentException(
        "Cannot convert value of type " + value.getClass().getName() + " to Character");
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
        return false;
    }
    // Build a set of all characters to search for (case-insensitive)
    Set<Character> searchChars = new HashSet<>();
    for (String s : searchStrArray) {
        if (s == null) {
            continue;
        }
        for (char c : s.toLowerCase().toCharArray()) {
            searchChars.add(c);
        }
    }
    // Check each character in the input string
    for (char c : str.toLowerCase().toCharArray()) {
        if (searchChars.contains(c)) {
            return true;
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Ensure we start with an odd number
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0) {
        candidate++;
    }
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2; // skip even numbers
        // Avoid integer overflow
        if (candidate < 0) {
            return Integer.MAX_VALUE;
        }
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if ((n & 1) == 0 || n % 3 == 0) return false;
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 5; i <= sqrtN; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

