public final byte[] toByteArray() {
    // Calculate total size of all buffers
    int totalSize = 0;
    for (byte[] buf : buffers) {
        if (buf != null) {
            totalSize += buf.length;
        }
    }

    // Allocate result array
    byte[] result = new byte[totalSize];

    // Copy each buffer into the result array
    int pos = 0;
    for (byte[] buf : buffers) {
        if (buf != null) {
            System.arraycopy(buf, 0, result, pos, buf.length);
            pos += buf.length;
        }
    }

    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                throw new Exception("Trailing backslash in string");
            }
            char next = str.charAt(++i);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 4 >= len) {
                        throw new Exception("Incomplete Unicode escape sequence");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence: \\u" + hex);
                    }
                    i += 4; // skip the 4 hex digits
                    break;
                default:
                    // Octal escape: up to 3 octal digits (0-7)
                    if (next >= '0' && next <= '7') {
                        int octal = next - '0';
                        int count = 1;
                        while (count < 3 && i + 1 < len) {
                            char d = str.charAt(i + 1);
                            if (d >= '0' && d <= '7') {
                                octal = (octal << 3) + (d - '0');
                                i++;
                                count++;
                            } else {
                                break;
                            }
                        }
                        sb.append((char) octal);
                    } else {
                        // Unknown escape sequence
                        throw new Exception("Invalid escape sequence: \\" + next);
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

