private int removeFromChildren(Category node) {
    List<Category> children = node.getChildren();
    if (children == null) {
        return 0;
    }
    int removed = 0;
    Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (!child.isActive()) {
            removed += countNodes(child);
            it.remove();
        } else {
            removed += removeFromChildren(child);
        }
    }
    return removed;
}

private int countNodes(Category node) {
    int count = 1;
    List<Category> children = node.getChildren();
    if (children != null) {
        for (Category c : children) {
            count += countNodes(c);
        }
    }
    return count;
}

