    int newLen = this.length + byteLength;
    if(newLen > this.capacity){
        int newCap = Math.max(newLen, this.capacity * 2);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(this.buffer, 0, newBuf, 0, this.length);
        this.buffer = newBuf;
        this.capacity = newCap;
