public byte readByte() throws IOException {
    // Refill the buffer if we have exhausted the current contents
    if (pos >= limit) {
        // Attempt to read more data into the buffer
        limit = in.read(buffer);
        pos = 0;
        // If no data was read, we are at EOF
        if (limit == -1) {
            throw new IOException("End of stream");
        }
        // In the unlikely event that zero bytes were read, try again
        if (limit == 0) {
            // Keep trying until we get data or hit EOF
            while (true) {
                limit = in.read(buffer);
                if (limit == -1) {
                    throw new IOException("End of stream");
                }
                if (limit > 0) {
                    break;
                }
            }
        }
    }
    // Return the next byte from the buffer
    return buffer[pos++];
}

