private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(0);
    }
    long running = 0;
    for (int i = n - 1; i >= 0; i--) {
        running += bounds.get(i);
        suffix.set(i, (int) running);
    }
    return new Pair<>(suffix, running);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        return;
    }
    // Ensure indices are within bounds
    int n = arr.length;
    if (from < 0) {
        from = 0;
    }
    if (to >= n) {
        to = n - 1;
    }
    // If the range is invalid, do nothing
    if (from >= to) {
        return;
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

